package com.miniforce.controller;
import com.miniforce.dto.ProblemDtos.*; import com.miniforce.dto.SubmissionDtos.SubmissionResponse; import com.miniforce.model.Difficulty; import com.miniforce.model.User; import com.miniforce.service.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/problems") public class ProblemController {private final ProblemService problems;private final SubmissionService submissions;private final CurrentUser current;public ProblemController(ProblemService p,SubmissionService s,CurrentUser c){problems=p;submissions=s;current=c;}@GetMapping List<ProblemSummary> list(@RequestParam(required=false)String search,@RequestParam(required=false)Difficulty difficulty,@RequestParam(required=false)String topic){return problems.list(search,difficulty,topic,current.optional().orElse(null));}@GetMapping("/slug/{slug}") ProblemDetail getBySlug(@PathVariable String slug){return problems.getBySlug(slug,current.optional().orElse(null));}@GetMapping("/{id}") ProblemDetail get(@PathVariable Long id){return problems.get(id,current.optional().orElse(null));}@GetMapping("/{id}/hints") List<ProblemHintResponse> hints(@PathVariable Long id){return problems.hints(id);}@PostMapping ResponseEntity<ProblemDetail> create(@Valid @RequestBody ProblemRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(problems.create(r));}@PutMapping("/{id}") ProblemDetail update(@PathVariable Long id,@Valid @RequestBody ProblemRequest r){return problems.update(id,r);}@DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable Long id){problems.delete(id);return ResponseEntity.noContent().build();}@GetMapping("/{id}/test-cases") List<TestCaseResponse> tests(@PathVariable Long id){try{User u=current.require();if(u.getRole()==com.miniforce.model.Role.ADMIN)return problems.testCases(id);}catch(Exception ignored){}return problems.sampleTestCases(id);}@PostMapping("/{id}/test-cases") ResponseEntity<TestCaseResponse> addTest(@PathVariable Long id,@Valid @RequestBody TestCaseRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(problems.addTestCase(id,r));}@PutMapping("/test-cases/{id}") TestCaseResponse editTest(@PathVariable Long id,@Valid @RequestBody TestCaseRequest r){return problems.updateTestCase(id,r);}@DeleteMapping("/test-cases/{id}") ResponseEntity<Void> deleteTest(@PathVariable Long id){problems.deleteTestCase(id);return ResponseEntity.noContent().build();}@GetMapping("/{id}/submissions") List<SubmissionResponse> history(@PathVariable Long id){return submissions.forProblem(id,current.require());}}
